'use client';

import { useState } from 'react';

import { MinusIcon, PlusIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';

import { PLAN, SECTION } from './data';
import { FeatureTable } from './feature-table';
import { SlidingFigure } from './sliding-figure';

const PRICE_FORMAT = new Intl.NumberFormat('en', {
  style: 'currency',
  currency: 'XXX',
  maximumFractionDigits: 0,
});

function formatPrice(amount: number) {
  return PRICE_FORMAT.format(amount);
}

function seatsLabelOf(seats: number) {
  if (seats === 1) {
    return 'for 1 seat';
  }
  return `for ${seats} seats`;
}

function moreSeatsOf(seats: number) {
  const next = seats + 1;
  return Math.min(next, PLAN.maxSeats);
}

function fewerSeatsOf(seats: number) {
  const next = seats - 1;
  return Math.max(next, PLAN.minSeats);
}

export default function Pricing02() {
  const [seats, setSeats] = useState(PLAN.defaultSeats);
  const [direction, setDirection] = useState(1);
  const canRemoveSeat = seats > PLAN.minSeats;
  const canAddSeat = seats < PLAN.maxSeats;
  const total = seats * PLAN.pricePerSeat;
  const totalLabel = formatPrice(total);
  const seatPrice = formatPrice(PLAN.pricePerSeat);
  const seatCount = String(seats);
  const seatsLabel = seatsLabelOf(seats);

  function addSeat() {
    setDirection(1);
    setSeats(moreSeatsOf);
  }

  function removeSeat() {
    setDirection(-1);
    setSeats(fewerSeatsOf);
  }

  return (
    <section className='px-4 py-16 sm:px-6 sm:py-24 lg:px-8'>
      <div className='mx-auto flex max-w-6xl flex-col gap-10 sm:gap-14'>
        <div className='flex max-w-2xl flex-col gap-3'>
          <h2 className='text-2xl font-semibold text-balance sm:text-3xl'>
            {SECTION.title}
          </h2>
          <p className='text-muted-foreground text-base text-pretty'>
            {SECTION.description}
          </p>
        </div>
        <div className='grid items-start gap-10 lg:grid-cols-[22rem_minmax(0,1fr)] lg:gap-16'>
          <article className='surface-brand flex flex-col gap-6 rounded-xl p-6 sm:p-7 lg:sticky lg:top-8'>
            <div className='flex flex-col gap-1.5'>
              <h3 className='text-sm font-medium'>{PLAN.name}</h3>
              <p className='text-muted-foreground text-[13px]'>
                {PLAN.description}
              </p>
            </div>
            <p className='flex items-baseline gap-1.5'>
              <span className='text-4xl font-semibold tabular-nums'>
                {seatPrice}
              </span>
              <span className='text-muted-foreground text-[13px]'>
                per seat, per month
              </span>
            </p>
            <div className='flex items-center justify-between gap-4'>
              <span id='pricing-02-seats' className='text-[13px] font-medium'>
                Seats
              </span>
              <div
                role='group'
                aria-labelledby='pricing-02-seats'
                className='bg-card hairline-ring ring-foreground/12 dark:bg-foreground/[0.04] dark:ring-foreground/15 inline-flex items-center gap-1 rounded-full p-0.5 shadow-[0_1px_2px_rgb(0_0_0/0.05)]'
              >
                <Button
                  variant='ghost'
                  size='icon-sm'
                  className='rounded-full'
                  aria-label='Remove a seat'
                  disabled={!canRemoveSeat}
                  focusableWhenDisabled
                  onClick={removeSeat}
                >
                  <MinusIcon />
                </Button>
                <SlidingFigure
                  value={seatCount}
                  direction={direction}
                  className='min-w-6 justify-center text-[13px] font-medium'
                />
                <Button
                  variant='ghost'
                  size='icon-sm'
                  className='rounded-full'
                  aria-label='Add a seat'
                  disabled={!canAddSeat}
                  focusableWhenDisabled
                  onClick={addSeat}
                >
                  <PlusIcon />
                </Button>
              </div>
            </div>
            <div
              aria-live='polite'
              className='bg-foreground/[0.03] flex items-baseline justify-between gap-3 rounded-lg px-3 py-2.5'
            >
              <span className='text-muted-foreground text-[13px]'>
                Total per month
              </span>
              <span className='flex items-baseline gap-1.5 text-sm'>
                <SlidingFigure
                  value={totalLabel}
                  direction={direction}
                  className='font-semibold'
                />
                <span className='text-muted-foreground text-xs'>
                  {seatsLabel}
                </span>
              </span>
            </div>
            <Button size='lg' nativeButton={false} render={<a href='#' />}>
              {PLAN.action}
            </Button>
            <p className='text-muted-foreground text-xs'>{PLAN.footnote}</p>
          </article>
          <FeatureTable />
        </div>
      </div>
    </section>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
  useReducedMotion,
} from 'motion/react';

import { cn } from '@/registry/ndeko/lib/utils';

const COUNT_TRANSITION: Transition = {
  duration: 0.18,
  ease: [0.23, 1, 0.32, 1],
};

const SLIDE_DISTANCE = 8;

const COUNT_VARIANTS: Variants = {
  enter: (direction: number) => ({
    opacity: 0,
    y: direction * SLIDE_DISTANCE,
  }),
  visible: { opacity: 1, y: 0 },
  exit: (direction: number) => ({
    opacity: 0,
    y: direction * -SLIDE_DISTANCE,
  }),
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

function countVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return COUNT_VARIANTS;
}

type SlidingFigureProps = {
  value: string;
  direction: number;
  className?: string;
};

export function SlidingFigure({
  value,
  direction,
  className,
}: SlidingFigureProps) {
  const shouldReduceMotion = useReducedMotion();
  const countVariants = countVariantsOf(shouldReduceMotion);

  return (
    <span className={cn('relative inline-flex tabular-nums', className)}>
      <AnimatePresence mode='popLayout' initial={false} custom={direction}>
        <motion.span
          key={value}
          custom={direction}
          variants={countVariants}
          initial='enter'
          animate='visible'
          exit='exit'
          transition={COUNT_TRANSITION}
        >
          {value}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

import { FEATURE_GROUPS } from './data';

export function FeatureTable() {
  return (
    <table className='w-full text-[13px]'>
      <caption className='sr-only'>What the Studio plan includes</caption>
      <thead>
        <tr className='hairline-b border-border text-muted-foreground text-xs'>
          <th scope='col' className='pb-3 text-left font-medium'>
            Feature
          </th>
          <th scope='col' className='pb-3 text-right font-medium'>
            In the Studio plan
          </th>
        </tr>
      </thead>
      {FEATURE_GROUPS.map((group) => (
        <tbody key={group.title}>
          <tr>
            <th
              scope='rowgroup'
              colSpan={2}
              className='pt-7 pb-2 text-left text-sm font-medium'
            >
              {group.title}
            </th>
          </tr>
          {group.rows.map((row) => (
            <tr key={row.feature} className='hairline-b border-border'>
              <th scope='row' className='py-3 pe-4 text-left font-normal'>
                {row.feature}
              </th>
              <td className='text-muted-foreground py-3 text-right'>
                {row.value}
              </td>
            </tr>
          ))}
        </tbody>
      ))}
    </table>
  );
}

export const PLAN = {
  name: 'Studio plan',
  description:
    'One plan with every feature. You pay for each person who sends invoices.',
  pricePerSeat: 18,
  minSeats: 1,
  maxSeats: 50,
  defaultSeats: 3,
  action: 'Start a free month',
  footnote:
    'Example prices in a placeholder currency (¤), taxes added at checkout',
};

export const SECTION = {
  title: 'One price per person who sends invoices, every feature included',
  description:
    'No feature is held back for a bigger tier. Add a seat when someone new starts sending invoices, remove it when they stop.',
};

export type FeatureRow = {
  feature: string;
  value: string;
};

export type FeatureGroup = {
  title: string;
  rows: FeatureRow[];
};

export const FEATURE_GROUPS: FeatureGroup[] = [
  {
    title: 'Invoicing',
    rows: [
      { feature: 'Invoices per month', value: 'Unlimited' },
      { feature: 'Recurring invoices', value: 'Included' },
      { feature: 'Currencies', value: 'Any your client pays in' },
    ],
  },
  {
    title: 'Time',
    rows: [
      { feature: 'Timers and timesheets', value: 'Included' },
      { feature: 'Rates per person or per task', value: 'Included' },
    ],
  },
  {
    title: 'Getting paid',
    rows: [
      { feature: 'Payment links by card or transfer', value: 'Included' },
      { feature: 'Automatic reminders', value: 'Up to three per invoice' },
    ],
  },
  {
    title: 'Workspace',
    rows: [
      { feature: 'Clients', value: 'Unlimited' },
      { feature: 'Exports', value: 'CSV and PDF' },
      { feature: 'Support', value: 'Email, answered by a person' },
    ],
  },
];
